def process(roman_cities):
    import pandas as pd
    import numpy as np
    s = roman_cities.copy()

    # Filter to Greece
    s = s[s['Country'].astype(str).str.strip().str.lower() == 'greece'].copy()

    # Parse Barrington Atlas Rank, handling values like "4 or 5" by averaging
    def parse_rank(x):
        if pd.isna(x):
            return np.nan
        t = str(x).strip()
        if t == '' or t.lower() in {'nan', 'none'}:
            return np.nan
        # normalize separators
        tl = t.lower().replace('–', '-').replace('—', '-').replace('to', '-').replace('or', ' or ')
        # If contains 'or' with two numbers
        if ' or ' in tl:
            parts = [p.strip() for p in tl.split(' or ') if p.strip()]
            nums = []
            for p in parts:
                try:
                    nums.append(float(p))
                except:
                    pass
            if len(nums) == 2:
                return sum(nums)/2.0
        # Otherwise try direct numeric
        try:
            return float(t)
        except:
            return np.nan

    s['rank_num'] = s['Barrington Atlas Rank'].apply(parse_rank)
    return s[['Primary Key','Country','Barrington Atlas Rank','rank_num']]

def process(greece_ranks_clean) -> pd.DataFrame:
    import pandas as pd
    avg = greece_ranks_clean['rank_num'].mean()
    return pd.DataFrame([{'country':'Greece','avg_rank':avg,'n_cities':len(greece_ranks_clean)}])
